// qasyncDrainTimeout bounds the poll for the worker pool to drain the TV items to
// the ready terminal (INV-poll-bounded: never an unbounded hang).
const qasyncDrainTimeout = 10 * time.Second

// qasyncToken is the admin bearer token this QA driver uses.
const qasyncToken = "qa-async-admin-token"

// qasyncExpect is the independently-derived contract for one TV fixture: the
// cleaned title, season/episode, and resolution tv-parser MUST produce.
// resolution == "" means the field must be ABSENT.
type qasyncExpect struct {
	rel        string
	title      string
	season     int
	episode    int
	resolution string
}

// qasyncTVFixtures are the DIFFERENT fixtures this QA re-derivation uses (vs the
// golden's Show.Name/Игра престолов set). The release-group token (WEB-DL) and the
// 480p Cyrillic file exercise resolution/group stripping on inputs the golden does
// not cover.
var qasyncTVFixtures = []qasyncExpect{
	{rel: "Mandalorian.S02E03.720p.WEB-DL.mkv", title: "Mandalorian", season: 2, episode: 3, resolution: "720p"},
	{rel: "Чёрное зеркало S03E01.480p.mkv", title: "Чёрное зеркало", season: 3, episode: 1, resolution: "480p"},
}

// qasyncCorrupt is the zero-byte fixture driving the AC-6 unprobeable soft-fail. It
// has no SxxExx token, so tv-parser skips it and it stays 'pending' (no source
// succeeds -> never enriched -> never settles -> remains pending).
const qasyncCorrupt = "broken-qa.mkv"

// TestQA_AsyncAcceptance re-derives AC-1/AC-async/AC-lease/AC-ledger/AC-states
// independently of the coder's golden.
func TestQA_AsyncAcceptance(t *testing.T) {
	if testing.Short() {
		t.Skip("QA async acceptance: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — skipping QA async acceptance (INV-skip-clean)")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate the real media fixture AC-1 requires")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "qasync-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "qasync-base-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "qasync-tv-parser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "qasync-image-enricher", "./plugins/image-enricher")
	fixtureRoot := qasyncWriteFixtures(t)

	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, qasyncToken)
	client := &http.Client{Timeout: httpTimeout}
	libID := createLibrary(t, client, baseURL, qasyncToken, fixtureRoot)

	res := scanLibrary(t, client, baseURL, qasyncToken, libID)
	// AC-3: scan response shape unchanged; 2 real media + 1 zero-byte corrupt persisted.
	if res.Discovered != 3 || res.Persisted != 3 {
		t.Fatalf("AC-3: scan discovered=%d persisted=%d, want 3/3", res.Discovered, res.Persisted)
	}

	// AC-async: scan returned WITHOUT awaiting enrichment. >=1 item is still pending
	// immediately after the response (the corrupt fixture stays pending; non-flaky).
	if pending := len(asyncItemsByStatus(t, client, baseURL, qasyncToken, libID, "pending")); pending < 1 {
		t.Fatalf("AC-async: 0 pending items right after scan — scan blocked on enrichment")
	}

	byRel := qasyncWaitForReady(t, client, baseURL, libID, qasyncTVFixtures)

	t.Run("AC1_provenance_independent", func(t *testing.T) { qasyncAssertProvenance(t, byRel) })
	t.Run("AC1_parseTV_split", func(t *testing.T) { qasyncAssertParseTVSplit(t, byRel) })
	t.Run("AC6_softfail", func(t *testing.T) { qasyncAssertSoftFail(t, byRel) })
	t.Run("AC_states_filter", func(t *testing.T) { qasyncAssertStates(t, client, baseURL, libID) })
}

// qasyncWriteFixtures builds the DIFFERENT TV fixture tree under a temp dir: two
// real (ffmpeg-generated) TV files and one zero-byte corrupt file.
func qasyncWriteFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	for _, f := range qasyncTVFixtures {
		makeMedia(t, filepath.Join(root, f.rel))
	}
	mustWrite(t, filepath.Join(root, qasyncCorrupt), nil) // zero-byte -> AC-6 soft-fail
	return root
}

// qasyncWaitForReady polls the item listing until every QA TV fixture reaches
// 'ready', or fails with the last observed statuses on timeout (INV-poll-bounded).
func qasyncWaitForReady(t *testing.T, c *http.Client, baseURL string, libID int64, want []qasyncExpect) map[string]itemDTO {
	t.Helper()
	rels := make([]string, len(want))
	for i, w := range want {
		rels[i] = w.rel
	}
	deadline := time.Now().Add(qasyncDrainTimeout)
	for time.Now().Before(deadline) {
		byRel := indexByPath(t, listItems(t, c, baseURL, qasyncToken, libID))
		if qasyncAllReady(byRel, rels) {
			return byRel
		}
		time.Sleep(probeInterval)
	}
	byRel := indexByPath(t, listItems(t, c, baseURL, qasyncToken, libID))
	t.Fatalf("QA async drain did not settle %v to ready within %s; last: %s",
		rels, qasyncDrainTimeout, qasyncStatuses(byRel))
	return byRel
}

// qasyncAllReady reports whether every rel is present and status=='ready'.
func qasyncAllReady(byRel map[string]itemDTO, rels []string) bool {
	for _, rel := range rels {
		it, ok := byRel[rel]
		if !ok || it.Status != "ready" {
			return false
		}
	}
	return true
}

// qasyncStatuses renders per-item statuses for a timeout diagnostic.
func qasyncStatuses(byRel map[string]itemDTO) string {
	out := make([]string, 0, len(byRel))
	for rel, it := range byRel {
		out = append(out, rel+"="+it.Status)
	}
	return strings.Join(out, " ")
}

// qasyncAssertProvenance asserts AC-1 for the DIFFERENT fixtures via the INDEPENDENT
// qasyncDeriveShow derivation: sources.tv-parser carries cleaned title + season/
// episode + resolution, _provenance names tv-parser per field, _view.title is
// sourced, and _stages records an ok tv-parser entry. The cleaned title must NOT
// contain the resolution/release-group tokens. Table-driven.
func qasyncAssertProvenance(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, want := range qasyncTVFixtures {
		want := want
		t.Run(want.rel, func(t *testing.T) {
			it, ok := byRel[want.rel]
			if !ok {
				t.Fatalf("AC-1: %q not persisted; have %v", want.rel, pathsOf(byRel))
			}
			title, season, episode, resolution, dok := qasyncDeriveShow(qasyncStemOf(want.rel))
			if !dok {
				t.Fatalf("AC-1: %q did not yield a derivable SxxExx token (test bug)", want.rel)
			}
			// cross-check the independent derivation against the table expectation.
			if title != want.title || season != want.season || episode != want.episode || resolution != want.resolution {
				t.Fatalf("AC-1: %q derivation mismatch: got (%q,%d,%d,%q) want (%q,%d,%d,%q)",
					want.rel, title, season, episode, resolution, want.title, want.season, want.episode, want.resolution)
			}
			if it.Status != "ready" {
				t.Fatalf("AC-1: %q status = %q, want ready", want.rel, it.Status)
			}
			doc := parseAsyncDoc(t, it.Document)
			tv, ok := doc.Sources["tv-parser"]
			if !ok {
				t.Fatalf("AC-1: %q sources.tv-parser missing (sources=%v)", want.rel, doc.Sources)
			}
			if got := asyncStr(tv, "title"); got != want.title {
				t.Errorf("AC-1: %q tv-parser.title = %q, want %q", want.rel, got, want.title)
			}
			if qasyncContainsToken(want.title, want.resolution) {
				t.Errorf("AC-1: %q cleaned title %q leaked resolution token %q", want.rel, want.title, want.resolution)
			}
			if got := asyncInt(tv, "season"); got != want.season {
				t.Errorf("AC-1: %q tv-parser.season = %d, want %d", want.rel, got, want.season)
			}
			if got := asyncInt(tv, "episode"); got != want.episode {
				t.Errorf("AC-1: %q tv-parser.episode = %d, want %d", want.rel, got, want.episode)
			}
			qasyncAssertResolution(t, want.rel, tv, want.resolution)
			qasyncAssertProvenanceFields(t, want.rel, doc)
			if v := doc.View["title"]; asyncStr(v, "value") != want.title || asyncStr(v, "source") != "tv-parser" {
				t.Errorf("AC-1: %q _view.title = %v, want {value:%q,source:tv-parser}", want.rel, doc.View["title"], want.title)
			}
			if !asyncStageHas(doc.Stages, "tv-parser", "ok") {
				t.Errorf("AC-1: %q no _stages {tv-parser,ok}; stages=%v", want.rel, doc.Stages)
			}
		})
	}
}

// qasyncAssertResolution checks the resolution field: present+exact when expected,
// or absent when the fixture carries no resolution token.
func qasyncAssertResolution(t *testing.T, rel string, tv map[string]any, resolution string) {
	t.Helper()
	if resolution == "" {
		if _, leak := tv["resolution"]; leak {
			t.Errorf("AC-1: %q tv-parser.resolution present, want absent", rel)
		}
		return
	}
	if got := asyncStr(tv, "resolution"); got != resolution {
		t.Errorf("AC-1: %q tv-parser.resolution = %q, want %q", rel, got, resolution)
	}
}

// qasyncAssertProvenanceFields checks each enriched field has a _provenance entry
// naming tv-parser with a non-empty plugin_version.
func qasyncAssertProvenanceFields(t *testing.T, rel string, doc asyncDoc) {
	t.Helper()
	for _, field := range []string{"title", "season", "episode"} {
		p, present := doc.Provenance[field]
		if !present {
			t.Errorf("AC-1: %q _provenance.%s missing", rel, field)
			continue
		}
		if got := asyncStr(p, "plugin_id"); got != "tv-parser" {
			t.Errorf("AC-1: %q _provenance.%s.plugin_id = %q, want tv-parser", rel, field, got)
		}
		if asyncStr(p, "plugin_version") == "" {
			t.Errorf("AC-1: %q _provenance.%s.plugin_version empty", rel, field)
		}
	}
}

// qasyncAssertParseTVSplit is the structural/negative AC-1 proof for the DIFFERENT
// fixtures: base-scanner's parsed namespace is media-type-agnostic — NO TV field
// leaks (incl. release_group) — while the TV parse comes SOLELY from
// sources["tv-parser"]. relative_path is echoed verbatim.
func qasyncAssertParseTVSplit(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, want := range qasyncTVFixtures {
		it, ok := byRel[want.rel]
		if !ok {
			t.Fatalf("AC-1 split: %q not persisted; have %v", want.rel, pathsOf(byRel))
		}
		doc := parseAsyncDoc(t, it.Document)
		for _, bad := range []string{"season", "episode", "resolution", "release_group", "title"} {
			if _, leak := doc.Parsed[bad]; leak {
				t.Errorf("AC-1 split: %q parsed.%s present — TV parse must come from tv-parser only", want.rel, bad)
			}
		}
		if got := asyncStr(doc.Parsed, "relative_path"); got != want.rel {
			t.Errorf("AC-1 split: %q parsed.relative_path = %q, want %q", want.rel, got, want.rel)
		}
	}
}

// qasyncAssertSoftFail asserts AC-6 (the corrupt file still yields an item with an
// EMPTY ffprobe — unprobeable soft-fail) plus the lease observable: the corrupt
// item stayed pending (no source succeeded) and no item has duplicate _stages.
func qasyncAssertSoftFail(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	it, ok := byRel[qasyncCorrupt]
	if !ok {
		t.Fatalf("AC-6: %q not persisted (an unprobeable file must still yield an item); have %v", qasyncCorrupt, pathsOf(byRel))
	}
	if fp := parseAsyncDoc(t, it.Document).Ffprobe; len(fp) != 0 {
		t.Errorf("AC-6: %q ffprobe = %d bytes, want empty (unprobeable soft-fail)", qasyncCorrupt, len(fp))
	}
	// AC-lease observable: the corrupt item stayed pending (no source succeeded).
	if it.Status != "pending" {
		t.Errorf("AC-lease: %q status = %q, want pending (tv-parser skips non-TV; no source succeeds)", qasyncCorrupt, it.Status)
	}
	for _, want := range qasyncTVFixtures {
		item, present := byRel[want.rel]
		if !present {
			continue
		}
		doc := parseAsyncDoc(t, item.Document)
		// sources carries ONLY tv-parser (tmdb unloaded -> unavailable; kinopoisk CLIENT).
		for k := range doc.Sources {
			if k != "tv-parser" {
				t.Errorf("AC-lease: %q sources has %q (only tv-parser expected)", want.rel, k)
			}
		}
		if asyncHasDupStage(doc.Stages) {
			t.Errorf("AC-lease: %q duplicate _stages (same plugin_id+started_at); stages=%v", want.rel, doc.Stages)
		}
	}
}

// qasyncAssertStates asserts AC-states over HTTP via the unchanged ?status=
// passthrough: post-drain, ?status=ready returns exactly the two TV items and
// ?status=pending returns the corrupt fixture.
func qasyncAssertStates(t *testing.T, c *http.Client, baseURL string, libID int64) {
	t.Helper()
	ready := asyncItemsByStatus(t, c, baseURL, qasyncToken, libID, "ready")
	if len(ready) != len(qasyncTVFixtures) {
		t.Fatalf("AC-states: ?status=ready returned %d items, want %d; got %v", len(ready), len(qasyncTVFixtures), asyncPaths(ready))
	}
	pending := asyncItemsByStatus(t, c, baseURL, qasyncToken, libID, "pending")
	if len(pending) == 0 {
		t.Errorf("AC-states: ?status=pending returned 0 items post-drain; want %q (tv-parser skips non-TV)", qasyncCorrupt)
	}
}

// qasyncDeriveShow INDEPENDENTLY derives (title, season, episode, resolution) from a
// TV filename stem via regexp token classification — a deliberately different
// algorithm from the golden's hand-rolled ASCII byte scanner (asyncDeriveShow).
// Resolution is lowercased to match the tv-parser's emission (e.g. "720p").
var (
	qasyncSeasonEpisodeRe = regexp.MustCompile(`(?i)S(\d+)E(\d+)`)
	qasyncResolutionRe    = regexp.MustCompile(`(?i)(\d{3,4}p)`)
)

func qasyncDeriveShow(stem string) (title string, season, episode int, resolution string, ok bool) {
	m := qasyncSeasonEpisodeRe.FindStringSubmatchIndex(stem)
	if m == nil {
		return "", 0, 0, "", false
	}
	season, _ = strconv.Atoi(stem[m[2]:m[3]])
	episode, _ = strconv.Atoi(stem[m[4]:m[5]])
	// title = the prefix before the SxxExx token, separators normalized to spaces.
	prefix := strings.ReplaceAll(stem[:m[0]], ".", " ")
	prefix = strings.ReplaceAll(prefix, "_", " ")
	prefix = strings.ReplaceAll(prefix, "-", " ")
	title = strings.Join(strings.Fields(prefix), " ")
	if r := qasyncResolutionRe.FindStringSubmatchIndex(stem); r != nil {
		resolution = strings.ToLower(stem[r[2]:r[3]])
	}
	return title, season, episode, resolution, true
}

// qasyncStemOf strips the extension from a relative path's base.
func qasyncStemOf(rel string) string {
	return strings.TrimSuffix(filepath.Base(rel), filepath.Ext(rel))
}

// qasyncContainsToken reports whether the title contains the resolution token as a
// substring (it must not — the resolution is stripped into its own field).
func qasyncContainsToken(title, token string) bool {
	if token == "" {
		return false
	}
	return strings.Contains(strings.ToLower(title), strings.ToLower(token))
}
